"use client";
import { useState } from 'react';
import { parseEther } from 'viem';
import { getWalletClient } from '@/lib/client';

export default function Home() {
  const [account, setAccount] = useState<string | null>(null);

  const connectWallet = async () => {
    const client = await getWalletClient();
    if (client) {
      const [address] = await client.requestAddresses();
      setAccount(address);
    } else {
      alert("Please install XDCPay or MetaMask");
    }
  };

  const handleSupport = async (creatorAddress: `0x${string}`) => {
    const client = await getWalletClient();
    if (!client || !account) return alert("Connect wallet first!");

    try {
      const hash = await client.writeContract({
        address: '0x101807e57d80b927f480ebea9f61ab2f50389d15', // Your deployed contract
        abi: [{
          name: 'supportCreator',
          type: 'function',
          stateMutability: 'payable',
          inputs: [{ name: '_creator', type: 'address' }],
          outputs: [],
        }],
        functionName: 'supportCreator',
        args: [creatorAddress],
        value: parseEther('10'), // Tip 10 XDC
        account: account as `0x${string}`,
      });
      alert(`Success! TX Hash: ${hash}`);
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <main className="min-h-screen bg-black text-white p-8">
      <div className="max-w-2xl mx-auto">
        <div className="flex justify-between items-center mb-12">
          <h1 className="text-4xl font-bold tracking-tighter">HARD FORK 🍴</h1>
          <button 
            onClick={connectWallet}
            className="bg-blue-600 px-6 py-2 rounded-full font-semibold hover:bg-blue-700 transition"
          >
            {account ? `${account.slice(0,6)}...${account.slice(-4)}` : "Connect Wallet"}
          </button>
        </div>

        {/* Post Card */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden shadow-2xl">
          <img src="https://images.unsplash.com/photo-1639322537228-f710d846310a" alt="Dev" className="w-full h-64 object-cover" />
          <div className="p-6">
            <h2 className="text-xl font-bold">Hard Fork Protocol: V1 Deployed</h2>
            <p className="text-zinc-400 mt-2">The revenue splitter is live on Apothem. 5% infrastructure fee enabled.</p>
            <button 
              onClick={() => handleSupport('0x215c2ff021637ebeb98ef836f097a0aef44216c9')}
              className="mt-6 w-full bg-white text-black py-3 rounded-xl font-bold hover:bg-zinc-200 transition"
            >
              Support for 10 XDC
            </button>
          </div>
        </div>
      </div>
    </main>
  );
}